        if kind == 'one':
            if len(decoded) != 1: raise AccessError('INVALID_RESPONSE')
            return decoded[0]
        if kind == 'optional':
            if len(decoded) > 1: raise AccessError('INVALID_RESPONSE')
            return decoded[0] if decoded else None
